-- 2253 🏋️ Exercises from the book "diego-simeone-attacking-tactics-tactical-analysis-and-sessions-from-atl-tico-mad" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'diego-simeone-attacking-tactics-tactical-analysis-and-sessions-from-atl-tico-mad');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Build-up 6v6 to three mini goals', 'positional_game', 'opposed', 'in_possession', 34, 34, 'Tactical Situation 1 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Build up from the back by finding the free central midfielder, centre back or full back in the space left by the opponent''s front two.', 'Marked area around the halfway line; 3 mini goals at the attacking end and 2 mini goals at the coach''s end. Reds (2 CBs, 2 CMs, 2 FBs) v whites in a 4-2 shape from a 4-4-2.', 'Coach passes in to a red defender; reds work the ball to a central midfielder who has time to turn, or a CB carries forward, or a FB gets free when the middle is blocked, then score in any of the 3 mini goals. Whites defend those goals and counter into the 2 mini goals behind.', NULL, 'Change the whites'' shape to mimic a 4-2-3-1, 4-3-3 or 3-5-2 opponent. Progresses to Practice 2 (10v9 build-up game).', 'Quick 1-2 touch pass and move; look for and move into free space to receive.', '6v6', 12, 12, NULL, NULL, NULL, NULL, true, false, true, NULL, 10),
  ('Build-up from GK in 10v9 game', 'phase_of_play', 'opposed', 'in_possession', 35, 35, 'Tactical Situation 1 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Build up from the goalkeeper by exploiting the spaces the opponent''s shape leaves, then finish.', 'Practice 1 enlarged with 2 full-size goals and keepers; reds add 2 wide midfielders and a forward, whites add 2 centre backs, so 10v9 in the marked area.', 'Play starts from the red GK; reds build through the free spaces (CBs, CMs, FBs) and attack the big goal; whites defend and try to score at the other end.', NULL, 'Change the whites'' formation to 4-2-3-1, 4-3-3 or 3-5-2.', 'Quick 1-2 touch pass and move; find space to receive.', '10v9 + 2 GKs', 21, 21, NULL, NULL, NULL, NULL, true, true, true, NULL, 20),
  ('Drag the centre back passing pattern', 'combination', 'unopposed', 'in_possession', 42, 43, 'Tactical Situation 2 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Rehearse the forward drop and lay-off that pulls a centre back out, then use the space in the centre or out wide.', 'Half-pitch with 2 mini goals at the far end and marked zones for wide and central areas; reds in a back four, two CMs, wide mids and forwards; coaches with balls on each side.', 'Coach plays long to a CB who steps in and passes to the FB; ball is switched CM to CM, the forward drops and lays back, then the CM plays either into the centre for the wide midfielder (Scenario A: imagined CB followed the forward and FB stays wide) or out wide for the advancing full back (Scenario B: imagined FB tucked in), who scores in a mini goal.', NULL, 'Use a large goal with GK instead of mini goals; forward passes straight to the wide area instead of laying back. Repeat on the other side with CBs rotating; double up FB and wide mid positions for tempo.', 'Well-timed, synchronised runs of forward, wide midfielder and full back; accurate passing.', NULL, NULL, NULL, 'half pitch', NULL, NULL, NULL, true, false, true, NULL, 30),
  ('Drag the centre back functional practice', 'combination', 'passive', 'in_possession', 44, 45, 'Tactical Situation 2 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Read the opposing full back''s reaction and choose between the flank and the gap behind the dragged centre back.', '40 x 50 yards split into two halves worked at once; each side has a wide yellow zone (10 x 5 yds) and a central white zone (7 x 5 yds) in front of 2 goals; reds CB, CM, forward, wide mid, FB against a white CB and FB.', 'CB passes to CM, who lays back and opens up; on the third pass the forward drops to feet, the white CB follows, the forward lays back to the CM while wide mid and FB run. If the white FB tucks in, the CM chips to the FB in the wide zone, who crosses for the wide mid; if the FB holds, the pass goes to the wide mid in the central zone, who shoots.', 'White centre backs must always follow the dropping forward; receivers must collect inside the correct zone. Forward may pass direct to the FB if the opposing FB has already tucked in.', NULL, 'Synchronised timing of forward, wide midfielder and full back; read the full back''s position to decide; accurate passing and quick finishing.', NULL, NULL, NULL, '40 x 50 yards', 36.6, 45.7, NULL, true, false, true, NULL, 40),
  ('Drag the centre back 8v5 game', 'phase_of_play', 'overload', 'in_possession', 46, 47, 'Tactical Situation 2 Session: Practice 3', 'Simeone (Atletico Madrid)', 'Pull a centre back out with a dropping forward and exploit the space behind him or out wide against live defenders.', '40 x 50 yards with a full goal and GK; 8 red outfielders v 5 whites (back four plus a midfielder); a yellow receiving zone (40 x 5 yds) across the box edge with 2 wide white areas (10 x 5) and 2 red central areas (8 x 5); coaches with balls at the sides.', 'Reds pass into a forward who drops; the CB follows, the forward lays back to the CM, who plays behind the CB to the wide mid (FB held position, Scenario A) or out wide for the overlapping full back to cross (FB tucked in, Scenario B). On a wrong decision the coach serves to the whites, who counter and must score within 12-15 seconds.', 'White CBs must follow the forwards; white CBs and GK cannot enter the receiving zone.', 'Add 2 more white midfielders; reds may score any way, but a goal from dragging the CB and choosing correctly counts 3.', 'Synchronised movement of forward, wide midfielder and full back; read the full back''s position and choose correctly.', '8v5 + GK', 14, 16, '40 x 50 yards', 36.6, 45.7, NULL, true, true, true, NULL, 50),
  ('Drag the centre back 10v10 game', 'conditioned_game', 'opposed', 'in_possession', 48, 48, 'Tactical Situation 2 Session: Practice 4', 'Simeone (Atletico Madrid)', 'Apply dragging a centre back out and exploiting wide or central space in a near-full game.', '10v10 plus GKs over most of a pitch; one big goal with GK for reds to attack, 2 mini goals at the other end; marked 2 white wide areas (15 x 10 yds) and 2 red central areas (8 x 10 yds) in the final third.', 'Reds start and aim to draw a CB out by passing into a dropping forward, then go wide or behind the CB depending on the full back''s position; whites defend and counter to the mini goals.', 'White CBs must follow the forwards every time. Reds score any way, but 3 goals if from these tactics. Forwards may pass direct out wide if the full back has tucked in.', '11v11 on two-thirds of the pitch, same 3-goal bonus.', NULL, '10v10 + GKs', 21, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 60),
  ('Full back high options passing pattern with finish', 'combination', 'unopposed', 'in_possession', 55, 56, 'Tactical Situation 3 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Rehearse the four combinations open to a full back who receives high up the flank: ball in behind for the wide midfielder, inside to the forward, inside to a dropping wide midfielder, or a 1-2 with the forward.', 'About half a pitch with a goal and GK at each end; mannequins as defenders; groups of central midfielder (A), full back (B), wide midfielder (C) and forward (D) working from both ends at once.', 'GK serves to A, who lays it into B''s run; A plays B forward on the run. B then picks an option: through ball for C''s run to cross for D, pass inside to D to turn and shoot, pass into C who has bent his run inside around the mannequin, or a 1-2 with D then cross for C. Players rotate A to B to C to D.', 'Forward stays level with the mannequin (offside line); GKs swap ends after a few reps; switch side after working the right.', 'Options 1-2 shown first, then options 3-4; repeat on the left side.', 'Forward and wide midfielder move in sync; quick accurate passing in 1-2 touches; clean finishing.', '2 groups of 4 + 2 GKs', 10, NULL, 'half a pitch', NULL, NULL, NULL, true, true, true, NULL, 70),
  ('Full back reads centre backs, 8v2 functional', 'phase_of_play', 'opposed', 'in_possession', 57, 59, 'Tactical Situation 3 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Full back receiving high up reads how the two opposing centre backs react and picks the right option to break through.', '40 x 50 yard area to a goal with GK; 10 x 10 white wide zones, 10 x 12 yellow zones beyond them and two 6 x 6 red zones in the centre; reds attack against 2 white centre backs.', 'Central midfielders circulate three passes and switch out wide to the full back in the white zone as the wide midfielder runs forward. Depending on the centre backs: pass in behind for the wide midfielder to cross; if a centre back tracks the winger, the forward drops into the red zone, turns and shoots or slips the other forward; or the forward drags the centre back and the wide midfielder receives in the red zone.', NULL, 'Scenarios A-C by centre back reaction; if the wide midfielder doesn''t run, full back can play a 1-2 with the forward and cross. Repeat on the right side.', 'Synchronise forward and wide midfielder movements; read the centre backs and decide accordingly.', '8 reds v 2 CBs + GK', 11, NULL, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 80),
  ('Full back options 9v8 small sided game', 'small_sided_game', 'opposed', 'in_possession', 60, 61, 'Tactical Situation 3 Session: Practice 3', 'Simeone (Atletico Madrid)', 'Apply full back high-up options in a live game with a counter threat.', 'Same 40 x 50 yard zoned area with a goal and GK at each end; 9v8.', 'Reds build from their GK and try to work the ball out to a full back in the wide white zone, read the defence and combine to score; whites counter if they win it.', 'Goal after full back receives in wide zone and correct combination = 3 goals; whites must score within 12-15 seconds of winning the ball; if reds fail, coach feeds whites a new ball; white full backs stay inside the wide white zones.', NULL, 'Synchronised forward/wide midfielder runs; decide by the centre back''s reaction.', '9v8 + 2 GKs', 19, NULL, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 90),
  ('Full back options 11v11 conditioned game', 'conditioned_game', 'opposed', 'in_possession', 62, 62, 'Tactical Situation 3 Session: Practice 4', 'Simeone (Atletico Madrid)', 'Bring the full back''s high-up decision making into a full team game.', '11v11 on two thirds of a pitch with the wide and central zones marked; reds attack the big goal, whites counter to two goals at the other end.', 'Reds start from their GK and try to score by getting a full back on the ball in the wide white zone and reading the centre back''s reaction.', 'Goal from the full back route after receiving wide = 3 goals.', 'Remove the zones once players read the situation well.', 'As previous practice.', '11v11', 22, 22, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 100),
  ('Full back and wide midfielder sync technical', 'combination', 'unopposed', 'in_possession', 68, 68, 'Tactical Situation 4 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Coordinate the wide midfielder dropping inside and the full back pushing on, then pick the right outlet.', '35 x 45 yard area with mini goals; 5 x 8 yard wide zones and 4 x 4 central boxes; mannequins; centre back (A), central midfielder (B), full back (C), wide midfielder (D); run from both ends.', 'A passes to B who drops, they play a 1-2 and B opens up. On the third pass D drops and C goes forward. B either finds C in the wide zone to dribble and cross into a mini goal, or finds D in the central box to turn and finish in a mini goal.', 'Rotate A to B to C to D to A.', 'Switch to the left side after the right.', 'Timing between full back and wide midfielder; accurate passing.', '8+ (2 groups of 4)', 8, NULL, '35 x 45 yards', 41.1, 32.0, NULL, true, false, true, NULL, 110),
  ('Full back and wide midfielder sync with finish', 'combination', 'unopposed', 'in_possession', 69, 69, 'Tactical Situation 4 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Same synchronised wide movements finishing on a real goal with GK.', '40 x 50 yard area split in two halves, each with a goal and GK; 12 x 5 yard wide zones and a 25 x 5 central zone; mannequins; both halves work at once.', 'Centre back passes to the dropping central midfielder, 1-2, midfielder opens up. On the third pass the wide midfielder drops and full back goes. Left side: full back fed wide to dribble and cross for the forward. Right side: wide midfielder fed in the central zone, turns and plays the forward in.', 'Two players in each wide midfielder/forward position keep tempo; centre back and central midfielder swap each rep.', NULL, 'Synchronised movements; quick accurate passes and finish.', '2 groups + 2 GKs', 12, NULL, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 120),
  ('Wide overload 10v4 functional practice', 'phase_of_play', 'overload', 'in_possession', 70, 71, 'Tactical Situation 4 Session: Practice 3', 'Simeone (Atletico Madrid)', 'Create and use a 2v1 wide by reading whether the opposing full back follows the dropping wide midfielder.', 'Two thirds of a pitch, goal with GK; white back four (2 full backs + 2 centre backs); mannequins in midfield; wide and central zones marked; coaches with balls on each flank.', 'Coach plays long to a centre back; reds combine until a central midfielder opens up. If the white full back follows the dropping wide midfielder, pass to the full back wide to dribble and cross; if he holds, play into the wide midfielder''s feet centrally to turn and slip the forward.', NULL, 'Scenario A (full back follows) and B (holds position).', 'Synchronised wide movements; read the full back; accurate passes and crosses; quick finishing.', '10v4 + GK', 15, NULL, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 130),
  ('Wide overload 10v10 conditioned game', 'conditioned_game', 'opposed', 'in_possession', 72, 72, 'Tactical Situation 4 Session: Practice 4', 'Simeone (Atletico Madrid)', 'Build overloads out wide through full back and wide midfielder movements in a full game.', '10v10 (+GK) on two thirds of a pitch; zones can stay or go; whites counter to 2 mini goals.', 'Reds try to create a wide overload and score; whites win it and score in the mini goals.', 'First 5 minutes: white central midfielders can''t enter the central zone unless a pass goes to a red wide midfielder or full back.', '11v11 on 2/3 pitch, reds score any way but a goal from the wide midfielder/full back overload counts 3.', 'As previous practice.', '10v10 + GK', 21, 22, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 140),
  ('Long passes behind the full back pattern', 'combination', 'unopposed', 'in_possession', 84, 85, 'Tactical Situation 5 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Rehearse ways to get a forward in behind the opposing full back.', 'Pitch split into two halves, each with goal and GK; mannequins; a target zone in each wide channel; centre back (A), central midfielder (B), full back (C), wide midfielder (D), strong side forward (E), weak side forward (F).', 'GK serves long to A, who plays a 1-2 with B around the mannequin; D drops. A then chooses: aerial ball into the zone for E; pass to C who drives a ground pass into the zone for E; pass to D who plays first time into F, who turns and puts E in; or D to F who plays first time into the zone for E.', 'After each rep A swaps with B, C with D, E with F.', 'Options 1-2 then options 3-4.', 'Wide midfielder and forward in sync; accurate well-timed passes; finishing.', '2 groups of 6 + 2 GKs', 14, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Forward runs behind full back, functional', 'phase_of_play', 'passive', 'in_possession', 86, 88, 'Tactical Situation 5 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Exploit the space vacated when the opposing full back follows the dropping wide midfielder.', '40 x 50 yard area to a goal with GK; two 8 x 7 yard wide target zones; 2 white full backs; mannequins in midfield; coaches with balls on both flanks.', 'Coach feeds a centre back, who links with central midfielders; the wide midfielder drops and the white full back follows. Then: centre back plays aerial into the zone for the forward; or centre back to full back who drives a ground ball in for the forward; or wide midfielder plays inside to the weak side forward, who sets the other forward into the zone.', 'White full backs are coached to follow the wide midfielders when they drop.', 'White full backs decide themselves whether to follow; add 2 white centre backs.', 'Wide midfielder and forward in sync; decide by the full back''s reaction.', 'reds v 2 FBs + GK', 12, NULL, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 160),
  ('Behind the full back 9v8 functional game', 'small_sided_game', 'opposed', 'in_possession', 89, 89, 'Tactical Situation 5 Session: Practice 3', 'Simeone (Atletico Madrid)', 'Drag the opposing full back out and attack the space behind him in a live game.', '40 x 50 yards, goals and GKs at both ends; 40 x 20 white low zone, 40 x 5 red high zone and two small yellow zones behind the full backs.', 'Red GK starts; reds pull a white full back out of position and score in the space behind; whites counter on a wrong decision.', 'White centre backs and full backs can''t enter the red zone; red full backs stay in the low zone; white full backs always follow the red wide midfielders; whites score within 12-15 seconds after a red error, coach feeds a new ball.', NULL, 'Read the full back''s reaction and choose the right route.', '9v8 + GKs', 19, NULL, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 170),
  ('Behind the full back 10v10 conditioned game', 'conditioned_game', 'opposed', 'in_possession', 90, 90, 'Tactical Situation 5 Session: Practice 4', 'Simeone (Atletico Madrid)', 'Score by getting a forward in behind the opposing full back in a full game.', '10v10 (+GK) on two thirds of a pitch, zones optional; whites counter to 2 mini goals.', 'Reds start 6v5 in the low white zone (one white central midfielder must stay out), build out and look to play a forward in behind a full back.', 'Red full backs stay in the low zone in the first phase, then may join once the forward pass goes; any goal counts but one from exploiting space behind a full back = 3; whites score in mini goals within 12-15 seconds of winning it.', NULL, 'As previous practice.', '10v10 + GK', 21, 22, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Forward drops or runs behind, technical finish', 'combination', 'unopposed', 'in_possession', 97, 100, 'Tactical Situation 6 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Read whether the weak side forward is close enough to attack space behind a centre back who follows the dropping forward, and choose who runs in behind.', '35 x 45 yard area to a goal with GK; two 5 x 8 yard central target boxes; mannequins; red and blue cones mark where the weak side forward stands (red = close enough, blue = too far).', 'Central midfielder plays to the full back, who drops and combines with the wide midfielder around a mannequin, then back to the central midfielder. If the weak side forward is on the red cone he gets the aerial ball into the box and shoots; on the blue cone the far wide midfielder runs into the box instead. Combination versions: pass into the forward''s feet, lay-off, then a 1-2 touch ball into the box for the runner.', 'Scenario C/D passes in 1-2 touches; two players per wide midfielder and forward spot for tempo.', 'Scenarios A-D: weak side forward or wide midfielder in behind, direct or after a combination; play from either side.', 'Forwards and wide midfielders in sync; read the weak side forward''s position; well-timed 1-2 touch passes and quick finishing.', 'about 12 + GK', 10, NULL, '35 x 45 yards', 41.1, 32.0, NULL, true, true, true, NULL, 190),
  ('Forward drops, weak-side forward exploits space', 'phase_of_play', 'opposed', 'in_possession', 101, 102, 'Tactical Situation 6 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Central midfielder reads the centre backs'' reaction to a dropping forward and picks the right pass to exploit the space behind.', '40 x 50 yard area in front of a goal with GK; two 5 x 8 yard white zones just behind where the 2 white centre backs stand; mannequins as other defenders; red full backs, central midfielders, wide midfielders and 2 forwards start in shape.', 'Play starts left or right with a set 4-pass build-up ending at the central midfielder. One forward drops; if his centre back follows, the midfielder plays the other (weak-side) forward into the vacated zone to finish. Scenario B: the other centre back steps to press the forward, who lays it square first time to the weak-side wide midfielder, who releases the strong-side wide man running into the space to shoot.', 'White centre backs are semi-passive and choose freely whether to follow, press or let the forward turn.', 'Add 2 white full backs. Wide midfielder and forward positions can be doubled up to keep tempo high.', 'Wide midfielders and forwards move in sync; read the weak-side forward and the centre back''s reaction; accurate passing and finishing.', 'about 10 reds + GK v 2 white centre backs (+2 full backs in progression)', 13, 16, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 200),
  ('Dropping forward 9v8 game with counter', 'small_sided_game', 'opposed', 'in_possession', 103, 103, 'Tactical Situation 6 Session: Practice 3', 'Simeone (Atletico Madrid)', 'Create and use space behind a centre back by a forward dropping, with the defending team countering on regains.', '40 x 50 yard pitch with a goal and GK at each end; a 40 x 5 yard red high zone across the white defensive line plus 2 small white areas marking the space behind the white centre backs.', '9v8 game. Reds attack and look for a forward to drop and either receive and turn or drag a centre back out so a team-mate can attack the space. Whites who win the ball try to score within 10-12 seconds.', 'Reds may score in any way, but a goal after exploiting space behind a centre back or a forward turning free counts 3. Whites may not enter the red zone unless a red receives there; white GK cannot enter it. Wrong decision or bad pass by reds = coach serves a ball to whites to score in 10-12 seconds.', NULL, 'Decide by the weak-side forward''s position and the centre back''s reaction.', '9v8 (incl GKs)', 17, 17, '40 x 50 yards', 45.7, 36.6, NULL, true, true, true, NULL, 210),
  ('11v11 dropping forward conditioned game', 'conditioned_game', 'opposed', 'in_possession', 104, 104, 'Tactical Situation 6 Session: Practice 4', 'Simeone (Atletico Madrid)', 'Apply the dropping-forward patterns in a full-team game.', '11v11 in two-thirds of a pitch, goals and GKs at both ends; zones behind the centre backs can be marked or left off.', 'Reds build up and use a forward dropping to create space behind a centre back, or to receive and turn. Whites win the ball and counter-attack.', 'Goal after exploiting space created behind a centre back or a forward turning free = 3 goals. Whites must score within 10-12 seconds of winning the ball.', NULL, 'Wide midfielders and forwards in sync; read the weak-side forward and the opposing centre back.', '11v11', 22, 22, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Weak-side forward drops, wide midfielder runs behind', 'phase_of_play', 'passive', 'in_possession', 109, 110, 'Tactical Situation 7 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Weak-side forward drops to pull his centre back out so the wide midfielder can run into the space, or receives and turns if the centre back holds.', 'Middle and final third with goal and GK; red zone between the lines in front of 2 white centre backs, small yellow start squares for the central midfielders; mannequins as other defenders; red centre backs, central midfielders, wide midfielders and 2 forwards.', 'A centre back starts and after 4 passes a central midfielder receives in the yellow square. The weak-side forward drops. If centre back No.4 follows, the wide midfielder on that side runs in behind for a long direct pass and finishes. Scenario B: the centre back holds, so the forward receives unmarked in the red zone, turns and slips in the other wide midfielder or forward to shoot.', NULL, NULL, 'Synchronised movement of wide midfielders and forwards; read the centre back''s reaction and choose the pass.', 'about 10 reds + GK v 2 white centre backs', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Dropping forward with full backs: space wide', 'phase_of_play', 'opposed', 'in_possession', 111, 112, 'Tactical Situation 7 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Read the reactions of both centre backs and full backs to a dropping forward and attack the space behind or out wide.', 'As the previous practice, plus 2 white full backs and 2 wide areas for the red full backs to run into.', 'Phase 1 (5-6 min): white centre backs always follow the dropping forward. If the white full back holds, the wide midfielder runs behind the centre back for an aerial pass; if the full back tucks across, the red full back runs into the wide area for a switch. After the wide pass reds attack 4 white defenders and GK. Phase 2 (5-6 min): centre backs decide freely; if they hold, the forward is found to feet to turn and launch a 4v4.', NULL, 'Phase 2 frees the centre backs to choose whether to track the forward.', 'Synchronised movement of wide midfielders and forwards; decide from the defensive reactions of the centre backs and full backs.', 'about 10 reds + GK v 4 white defenders', 15, 15, NULL, NULL, NULL, 12.0, true, true, true, NULL, 240),
  ('11v11 weak-side forward drop game', 'conditioned_game', 'opposed', 'in_possession', 113, 113, 'Tactical Situation 7 Session: Practice 3', 'Simeone (Atletico Madrid)', 'Use forward drops to open space for wide midfielders and full backs in a full game.', '11v11 in two-thirds of a pitch, goals and GKs at both ends; areas behind the defence and out wide can be marked or not.', 'Reds build up and either forward (weak or strong side) drops so play is not predictable, then exploit the space created. Whites counter on winning the ball.', 'Goal after exploiting space made by a dropping forward = 3 goals. Whites must score within 12-15 seconds of winning the ball.', NULL, 'Wide midfielders and forwards move in sync; read the centre backs'' and full backs'' reactions.', '11v11', 22, 22, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 250),
  ('Wide midfielder tucks in for central overload', 'combination', 'unopposed', 'in_possession', 119, 120, 'Tactical Situation 8 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Wide midfielder moves inside between the lines to overload the centre and play in a forward.', 'Two parallel half-pitch channels side by side, each with a goal and GK; mannequins as defenders (3 in a triangle near a white square); central midfielders, wide midfielder and 2 forwards per channel.', 'Phase 1 (5-6 min): central midfielders play a 1-2 and the receiver finds the wide midfielder moving inside beyond the first mannequin; he plays first time between the mannequins to the strong-side forward, or uses the weak-side forward as a link to set the other forward through to shoot. Phase 2: one mannequin moves forward (centre back holds), so the wide midfielder receives, turns and plays the final pass in behind.', NULL, 'Replace the central mannequin with a passive white centre back; the wide midfielder reads him and chooses first-time pass or receive-and-turn.', 'Forwards and wide midfielders in sync; accurate, well-timed passing; open body shape and quick turns; accurate finishing.', 'about 5 per channel + GK', 10, 14, NULL, NULL, NULL, 12.0, true, true, true, NULL, 260),
  ('Central overload dynamic zonal practice', 'phase_of_play', 'opposed', 'in_possession', 121, 121, 'Tactical Situation 8 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Win a low-zone 4v2, then exploit a central overload by the wide midfielder against the white back line.', 'Pitch split into a marked low zone (reds 4v2) with 2 mini goals behind it, a red zone between the lines and a final zone with full goal and GK; white centre backs and mannequins defend.', 'Reds play 4v2 in the low zone to free a central midfielder beyond the white forwards. The wide midfielder moves inside to overload and either plays first time in behind or receives and turns depending on the centre back; if pressed, the weak-side forward links to send the other forward into the space behind.', 'If whites win the ball they counter to the mini goals within 12-15 seconds; if won in the low zone, within 6 seconds.', NULL, 'Wide midfielder reads the centre back''s reaction to choose between pass in behind and receive-and-turn.', 'about 9 reds + GK v 2 forwards + 2 centre backs + GK', 15, 16, NULL, NULL, NULL, NULL, true, true, true, NULL, 270),
  ('11v11 attacking through the centre game', 'conditioned_game', 'opposed', 'in_possession', 122, 122, 'Tactical Situation 8 Session: Practice 3', 'Simeone (Atletico Madrid)', 'Create central overloads with the wide midfielder in a full game and choose the right final action.', '11v11 in two-thirds of a pitch, goals and GKs at both ends; central zones optional.', 'Reds build and the wide midfielder moves inside to overload; he reads the centre back and receives, turns and plays a final pass, or plays first time in behind. Whites counter on regains.', 'Goal after an overload in the centre = 3 goals. Whites must score within 10-12 seconds of winning the ball.', NULL, 'Forwards and wide midfielders in sync; read the opposing centre back.', '11v11', 22, 22, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Blind-side run for long pass, mannequins', 'combination', 'unopposed', 'in_possession', 126, 126, 'Tactical Situation 9 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Time a run on the blind side of a centre back to receive a long aerial pass and finish.', 'Half pitch with goal and GK; mannequins as a back line and midfield; 2 white target areas either side of the box; red centre backs, central midfielders and 2 forwards.', 'Centre backs and central midfielders pass in a set pattern; on the 4th pass the receiving midfielder looks up as the weak-side forward bends a run behind the blind side of the centre-back mannequin. The midfielder lofts a long pass into his path and he finishes in 2 touches.', 'Ball must be received inside the white areas.', NULL, 'Run timed on the defender''s blind side so he cannot see ball and forward together; accurate passing, receiving and finishing.', '6 reds + GK', 7, 7, 'half pitch', NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Blind-side run dynamic zonal practice', 'phase_of_play', 'opposed', 'in_possession', 127, 127, 'Tactical Situation 9 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Free a central midfielder in a 4v2, then hit a blind-side run with a long pass.', 'Low zone (reds 4v2 v white forwards) with 2 mini goals behind; middle red area for the white centre backs; 5 x 8 yard small areas inside the box; goal and GK; coaches with balls at the sides; mannequins.', 'Reds play 4v2 to find a free central midfielder beyond the white forwards. The weak-side forward runs on the blind side of his centre back into the small area and the midfielder plays a long pass for him to finish past the GK.', 'White centre backs defend only inside the red area. Forwards must receive the long pass in the small areas and have max 2 touches. If the forward fails to receive, the coach serves to the white forwards who attack the mini goals within 10 seconds.', NULL, NULL, 'about 8 reds + GK v 2 forwards + 2 centre backs', 13, 14, NULL, NULL, NULL, NULL, true, true, true, NULL, 300),
  ('10v10 blind-side run conditioned game', 'conditioned_game', 'opposed', 'in_possession', 128, 128, 'Tactical Situation 9 Session: Practice 3', 'Simeone (Atletico Madrid)', 'Score from blind-side runs onto long passes in a game, with whites countering.', '10v10 (+GK) in two-thirds of a pitch; 50 x 8 yard white zone in front of the box for forwards to receive; reds attack the goal with GK, whites counter into 2 mini goals.', 'Reds build and look for a long pass to a forward running on a defender''s blind side into the white zone to finish. Whites who win it counter-attack.', 'Goal after a blind-side run = 3 goals. Whites may not enter the white zone until a red receives there; white GK may not enter it. Whites score within 12-15 seconds.', '11v11 in two-thirds of the pitch with a full goal and GK added for the reds to attack.', NULL, '10v10 +GK', 21, 22, '2/3 of a pitch; zone 50 x 8 yards', NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Counter after winning ball wide, passive CBs', 'transition', 'opposed', 'to_attack', 142, 143, 'Transition Tactical Situation 1 Session: Practice 1', 'Simeone (Atletico Madrid)', 'Win the ball in a wide 3v3 and counter quickly with an indirect (wide cross) or direct (inside pass) threat.', 'Two 15-yard wide squares (adjustable) holding wide midfielders, full backs and central midfielders 3v3; 10-yard yellow square for the white forward in front of the white goal; red goal with GK at the far end; 2 coaches stand as passive centre backs.', 'Coach passes to the white full back in a wide 3v3; whites try to reach their forward in the yellow square to score. The 3 reds win it and counter to score within 8 seconds: Scenario A forward pass to the wide forward who crosses; Scenario B pass inside to the central midfielder who threads it between the coaches for the forward to finish.', 'Reds score within 8 seconds of winning the ball. Any pass to the white forward must come from inside a wide area.', NULL, 'Quick decisions after winning the ball; forwards'' movements synchronised.', 'about 9 reds + GK v 7 whites + GK, 2 coaches', 18, 20, '15 x 15 yard wide squares; 10 x 10 yard central square', NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Counter after winning ball wide, active CBs', 'transition', 'opposed', 'to_attack', 144, 144, 'Transition Tactical Situation 1 Session: Practice 2', 'Simeone (Atletico Madrid)', 'Same counter-attack from a wide regain against 2 live centre backs.', 'As the previous practice but the coaches are replaced by 2 active white centre backs and a white GK.', 'White GK plays to a centre back, who passes into a wide area; the 3v3 plays out and reds counter as before against the live centre backs.', 'Any pass to the white forward must come from inside a wide area.', NULL, 'Quick decisions after winning the ball; forwards'' movements synchronised.', 'about 9 reds + GK v 9 whites + GK', 20, 22, NULL, NULL, NULL, NULL, true, true, true, NULL, 330),
  ('9v9 counter after wide regain game', 'transition', 'opposed', 'to_attack', 145, 145, 'Transition Tactical Situation 1 Session: Practice 3', 'Simeone (Atletico Madrid)', 'Win the ball 3v3 in wide areas and choose between crossing threat and inside pass for a direct threat in a game.', '9v9 in two-thirds of a pitch with 2 wide areas and a central yellow zone for the white forward in front of the white goal; red goal with GK at the other end.', 'White GK starts; whites must move the ball into a wide area and then find their forward in the yellow zone to score. Reds win it in the 3v3 and counter, either passing straight to the wide forward to cross or inside to the central midfielder to feed the No.9.', 'Any pass to the white forward must come from inside a wide area.', NULL, NULL, '9v9', 18, 18, '2/3 of a pitch', NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Counter after central win to No.9 square', 'transition', 'opposed', 'to_attack', 151, 151, 'Counter Attack After Winning the Ball in the Centre (Direct Threat): Practice 1', 'Simeone (Atletico Madrid)', 'Win the ball in the middle and counter fast with forwards giving forward passing options for a direct threat.', '15 yard central square with 2 white centre backs and 2 white central mids against 2 red forwards and 2 red central mids; white No.9 waits in a 10 yard yellow square; 2 red wide mids start outside the square; a goal and GK at each end, coaches with balls on the sides.', 'Coach feeds a white centre back and whites try to work the ball into No.9 in the yellow square to finish. The 4 reds in the square press to win it, then counter with the wide mids joining and must shoot inside 8 seconds.', 'Reds must score within 8 seconds of winning the ball; red wide mids only join for the counter.', 'Progresses to the 9v9 functional game on 2/3 of the pitch.', 'Decide quickly after the win; forwards move in sync; find and attack the gaps between white defenders; ball winner should have 3 forward options.', '4v4 in square + white No.9 + 2 red wide mids + 2 GKs', 13, 13, '15 x 15 yard square (size to level) plus 10 yard yellow square', 13.7, 13.7, NULL, true, true, true, NULL, 350),
  ('9v9 central-win counter attack game', 'conditioned_game', 'opposed', 'to_attack', 152, 152, 'Counter Attack After Winning the Ball in the Centre (Direct Threat): Practice 2', 'Simeone (Atletico Madrid)', 'Counter attack quickly after winning possession in the central area of a full game.', '9v9 on two-thirds of a pitch with a large central white zone and a yellow zone in front of the white goal for No.9; GK in each goal.', 'White GK starts to a centre back and whites try to reach No.9 in the yellow zone to score. The 4 reds in the central area press to win it and then counter, with the wide mids joining, to score as fast as possible.', 'Red wide mids shift with the ball and may enter the white area, joining the counter once possession is won; white full backs push on, circulate the ball and defend once it is lost; passes into No.9 must come from inside the central area.', NULL, 'Same as previous practice: quick decisions, synchronised forward runs, attack gaps.', '9v9 (+2 GKs)', 20, 20, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Forwards counter after winning ball wide', 'transition', 'opposed', 'to_attack', 166, 166, 'Session for Defensive and Counter Attack-Minded Positioning of the Forwards: Practice 1', 'Simeone (Atletico Madrid)', 'Use counter-attack-minded forward positioning to exploit space after winning the ball in a wide area.', 'Two 15 yard wide squares each holding the full back, wide mid and a central mid of both teams (3v3); 2 red forwards against 2 white centre backs in the middle; white No.9 in a 10 yard yellow square in front of the white goal; GK in each goal.', 'White GK plays to a centre back who passes to a full back in a wide square; whites try to get the ball to No.9 to score. Reds win it in the wide 3v3 and counter, choosing between the strong-side forward (indirect threat), a direct ball to the advanced forward, or inside to a central mid who finds the advanced forward (direct threat).', 'Any pass into white No.9 must be played from inside a wide area.', 'Variation in the centre (Practice 2) and functional games (Practices 3 and 4).', 'Read the three options after the win; quickest route is an inside pass to a free central player.', '3v3 in each wide square, 2v2 centre + white No.9, 2 GKs', NULL, NULL, '15 yard wide squares, 10 yard yellow square', 13.7, 13.7, NULL, true, true, true, NULL, 370),
  ('Forwards counter after winning ball centrally', 'transition', 'opposed', 'to_attack', 167, 167, 'Session for Defensive and Counter Attack-Minded Positioning of the Forwards: Practice 2 (Variation)', 'Simeone (Atletico Madrid)', 'After a central win, play straight to the advanced forward between the centre backs for a direct threat.', '15 yard central square with 2 white centre backs and 2 white central mids against 2 red forwards and 2 red central mids; white No.9 in a 10 yard yellow square; coaches with balls on the sides; GK in each goal.', 'Coach passes to a white centre back and whites try to reach No.9 to score. The red who wins the ball looks first to the advanced forward for a direct threat, otherwise to the other forward for an indirect threat.', 'Passes into white No.9 must come from inside the central area.', NULL, 'Immediate pass into space between the centre backs after the win.', '4v4 in square + white No.9 + 2 GKs', 11, 11, '15 x 15 yard square (size to level) plus 10 yard yellow square', 13.7, 13.7, NULL, true, true, true, NULL, 380),
  ('9v10 wide-win counter attack game', 'conditioned_game', 'opposed', 'to_attack', 168, 168, 'Session for Defensive and Counter Attack-Minded Positioning of the Forwards: Practice 3 (Progression)', 'Simeone (Atletico Madrid)', 'Win the ball in wide 3v3s and counter by picking the right forward option in a game.', '9v10 on two-thirds of a pitch with marked wide areas and a central yellow zone for white No.9; GK in each goal.', 'White GK starts, whites move the ball into a wide area then try to get it to No.9 to score. Reds win it in the wide 3v3 and counter via the strong-side forward, a direct pass to the advanced forward, or inside to the central mid.', 'Passes into white No.9 must be played from inside a wide area.', NULL, NULL, '9v10 (+GKs)', 21, 21, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 390),
  ('Central-win counter game, forward positioning', 'conditioned_game', 'opposed', 'to_attack', 169, 169, 'Session for Defensive and Counter Attack-Minded Positioning of the Forwards: Practice 4 (Variation)', 'Simeone (Atletico Madrid)', 'Exploit counter-attack-minded forward positioning after winning the ball centrally in a game.', 'Game on two-thirds of a pitch; central area holds 2 white centre backs and 2 white central mids v 2 red forwards and 2 red central mids; yellow zone for white No.9; GK in each goal, full backs and wide mids outside.', 'Whites build and aim to reach No.9; reds win it in the centre and the ball winner passes at once into the space between the centre backs to the advanced forward for a direct threat.', 'Red wide mids shift with the ball and may enter the white area, joining the counter; white full backs attack and defend once possession is lost; passes into No.9 must come from the central area.', NULL, NULL, NULL, NULL, NULL, '2/3 of a full pitch', NULL, NULL, NULL, true, true, true, NULL, 400),
  ('6v6 open ball counter attack', 'transition', 'opposed', 'to_attack', 177, 177, 'Counter Attack with an Open Ball Situation: Practice 1', 'Simeone (Atletico Madrid)', 'Recognise an open ball after a win and have forwards run into space in behind.', '4 white defenders across a middle band with 2 white forwards in a yellow zone behind the reds; 6 reds (2 forwards, 4 midfielders) between them; white GK in the goal the reds attack.', 'Whites pass across the back four looking for a through ball to a forward in the yellow zone. Reds stay compact to intercept; once they win it with no pressure, the forwards split into the spaces (wide and between the centre backs) to receive and score.', 'Reds must score within 8 seconds.', 'Practice 2 adds 2 white central mids (6v8).', 'Quick decisions right after winning; synchronised forward movements; fast runs into space.', '6v6 (+GK)', 13, 13, NULL, NULL, NULL, NULL, true, true, true, NULL, 410),
  ('6v8 open ball counter attack', 'transition', 'opposed', 'to_attack', 178, 178, 'Counter Attack with an Open Ball Situation: Practice 2 (Progression)', 'Simeone (Atletico Madrid)', 'Exploit the open ball before recovering midfielders can press.', 'As the 6v6 practice plus 2 white central mids who start outside the large white zone.', 'Whites look for through balls; when reds intercept they have time on the ball and must hit the forwards in the open spaces before the white mids close in, then score.', 'White central mids may only enter the white zone once possession is lost; reds score within 8 seconds.', NULL, 'Same as the previous practice.', '6v8 (+GK)', 15, 15, NULL, NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Read open or closed ball, counter', 'transition', 'opposed', 'to_attack', 186, 187, 'Counter Attack with a Closed Ball Situation: Practice 1', 'Simeone (Atletico Madrid)', 'Forwards read whether the ball winner is free or pressed and react with runs in behind or short support.', '25 x 15 yard main area with full backs, central mids and wide mids of both teams (6v6); white No.9 in a 15 x 10 yard yellow area; 2 red forwards beyond the main area beside mannequins; coaches on the sides, GK in each goal.', 'Coach feeds in and whites try to reach No.9 to score. When a red wins it unmarked (open ball) the forwards run into space for a straight pass; when he is pressed (closed ball) the forwards drop into passing lanes, and once a lay-off frees a team-mate they spin in behind.', NULL, 'Scenario A open ball, Scenario B closed ball; progresses to the 9v11 dynamic game.', 'Read the situation and react correctly; well-timed fast runs in behind without going offside.', '6v6 + 2 red forwards + white No.9 + 2 GKs', 17, 17, '25 x 15 yards main area, 15 x 10 yard yellow area', 22.9, 13.7, NULL, true, true, true, NULL, 430),
  ('9v11 closed ball counter attack game', 'conditioned_game', 'opposed', 'to_attack', 188, 188, 'Counter Attack with a Closed Ball Situation: Practice 2 (Progression)', 'Simeone (Atletico Madrid)', 'Break pressure after a win by short support to create an open ball, then counter.', 'Central 40 x 30 yard white zone and a 25 x 15 yard yellow zone for white No.9; reds in a 2-4-2, whites in a 4-3-3; coaches on the sides, GK in each goal.', 'Coach starts, whites try to reach No.9 to score. Reds win it and counter; with an extra midfielder the whites press the ball carrier at once, so reds must offer short options, free a player and then attack.', 'Reds score with a counter within 10-15 seconds.', 'If reds struggle against 3 midfielders, remove one white midfielder.', NULL, '9v11', 20, 20, '40 x 30 yard central zone, 25 x 15 yard yellow zone', 36.6, 27.4, NULL, true, true, true, NULL, 440),
  ('9v11 counter using full width', 'conditioned_game', 'opposed', 'to_attack', 194, 194, 'Exploiting Width During a Counter Attack in a Dynamic Conditioned Game', 'Simeone (Atletico Madrid)', 'When the middle is closed after a win, counter through the wide channels with the full back overlapping.', '45 x 65 yard area with a 25 x 25 yard central square, wide channels each side and a yellow zone for the white forwards; reds 2-4-2, whites 4-4-2; coaches on the sides, GK in each goal.', 'Coach starts, whites try to reach the forwards in the yellow zone to score. Reds win it and counter within 10-15 seconds; white wide players collapse into the central square to block, so reds go wide, e.g. full back receives on the run and plays in behind for a forward.', 'Counter through the central square scores 3 goals; while whites attack the pitch is only 35 yards wide (no wide zones), once reds win it they can use the full 45 yards.', NULL, NULL, '9v11', 20, 20, '45 x 65 yards, central square 25 x 25 yards', 59.4, 41.1, NULL, true, true, true, NULL, 450)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'diego-simeone-attacking-tactics-tactical-analysis-and-sessions-from-atl-tico-mad') b;
INSERT INTO schema_migrations (filename) VALUES ('2253-exercises-book-diego-simeone-attacking-tactics-tactical-analysis-and-sessio.sql') ON CONFLICT DO NOTHING;
